package com.labex.labexagent.run;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.labex.entity.AgentSubagentEvent;import com.labex.mapper.AgentSubagentEventMapper;import java.time.LocalDateTime;import java.util.List;import java.util.concurrent.ConcurrentHashMap;import org.springframework.stereotype.Service;
@Service public class AgentSubagentEventService {
 private final AgentSubagentEventMapper mapper;private final ConcurrentHashMap<Long,Object> locks=new ConcurrentHashMap<>();
 public AgentSubagentEventService(AgentSubagentEventMapper mapper){this.mapper=mapper;}
 public AgentSubagentEvent append(Long subagentId,String type,String payload){if(subagentId==null||subagentId<=0)throw new IllegalArgumentException("subagentId must be positive");if(type==null||type.isBlank())throw new IllegalArgumentException("event type is required");Object lock=locks.computeIfAbsent(subagentId,ignored->new Object());synchronized(lock){List<AgentSubagentEvent> latest=mapper.selectList(new LambdaQueryWrapper<AgentSubagentEvent>().eq(AgentSubagentEvent::getSubagentId,subagentId).orderByDesc(AgentSubagentEvent::getSequenceNo).last("LIMIT 1"));long sequence=latest.isEmpty()?1:latest.get(0).getSequenceNo()+1;AgentSubagentEvent event=new AgentSubagentEvent();event.setSubagentId(subagentId);event.setSequenceNo(sequence);event.setEventType(type.trim());event.setPayload(payload);event.setCreateTime(LocalDateTime.now());mapper.insert(event);return event;}}
 public List<AgentSubagentEvent> replay(Long subagentId,long afterSequence){return mapper.selectList(new LambdaQueryWrapper<AgentSubagentEvent>().eq(AgentSubagentEvent::getSubagentId,subagentId).gt(AgentSubagentEvent::getSequenceNo,Math.max(0,afterSequence)).orderByAsc(AgentSubagentEvent::getSequenceNo));}
}
